INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116915, 'spa', 'El Hifil causativo que significa rociar o hacer que un líquido (sangre, agua, ac', 'El Hifil causativo que significa rociar o hacer que un líquido (sangre, agua, aceite) sea aplicado en un contexto ritual o ceremonial deliberado. Esta es la acción sacerdotal principal en los ritos de purificación levíticos (Lv 4:6, 17; 14:7; Nm 19:19). En español, rociar transmite la naturaleza controlada y deliberada de la aspersión. Éxodo 29:21 describe a Moisés rociando sangre y aceite de unción sobre Aarón y sus vestiduras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116917, 'spa', 'El Qal intransitivo que indica que un líquido salpica, salta o se derrama sin ag', 'El Qal intransitivo que indica que un líquido salpica, salta o se derrama sin agencia ritual deliberada. La sangre salpica las vestiduras (Lv 6:27) o contra un muro (2 Re 9:33, de la muerte de Jezabel). En Isaías 63:3, las vestiduras del Guerrero Divino quedan salpicadas con la sangre de las naciones — en español, salpicar marca la naturaleza violenta e involuntaria de esta acción, distinta de la aspersión controlada del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116925, 'spa', 'Guiso, potaje', 'Un alimento espeso hervido de lentejas u otras legumbres, cocido en olla. Aparece solo seis veces pero con peso narrativo desproporcionado: es el instrumento de la renuncia de Esaú en Génesis 25:29-34 y el vehículo de una lección sobre provisión profética en 2 Reyes 4:38-40. Designa un guiso espeso, no una sopa ligera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116930, 'spa', 'Un nazareo — persona consagrada a Dios mediante un voto especial que implica tre', 'Un nazareo — persona consagrada a Dios mediante un voto especial que implica tres abstinencias: ni vino ni productos de la vid, ni corte del cabello, ni contacto con los muertos (Núm 6:1-21). Once apariciones se concentran en la legislación nazarea de Números 6, abarcando el inicio del voto (Núm 6:2), los rituales de conclusión (Núm 6:13-20) y el rasurado de la cabeza consagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116932, 'spa', 'Un consagrado o príncipe distinguido — alguien apartado no por voto formal sino ', 'Un consagrado o príncipe distinguido — alguien apartado no por voto formal sino por elección divina y honor entre sus pares. Tres apariciones surgen en poesía elevada: la bendición de Jacob llama a José ''el consagrado de sus hermanos'' (Gn 49:26), la bendición de Moisés repite ''el príncipe entre sus hermanos'' (Dt 33:16), y Lamentaciones 4:7 describe a los nobles de Jerusalén como otrora más puros que la nieve.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116935, 'spa', 'Una vid sin podar — una cepa dejada crecer silvestre y sin cosechar durante el a', 'Una vid sin podar — una cepa dejada crecer silvestre y sin cosechar durante el año sabático o jubilar. Solo dos apariciones (Lv 25:5, 11) aplican נָזִיר a la agricultura, y la lógica metafórica es elegante: así como el cabello del nazareo crece sin cortar como señal de consagración, la vid sabática crece sin poda como señal de que la tierra descansa para el SEÑOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116940, 'spa', 'El significado central', 'El significado central: agua que fluye a lo largo de un cauce — arroyos, ríos o wadis. El participio נֹזְלִים funciona casi como sustantivo independiente significando ''corrientes'', como en el Mar Rojo donde ''las aguas corrientes se levantaron como un muro'' (Éx 15:8). Las 12 apariciones confirman este como el sentido dominante de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116946, 'spa', 'Lluvia o humedad descendiendo de los cielos, enfatizando el movimiento vertical ', 'Lluvia o humedad descendiendo de los cielos, enfatizando el movimiento vertical hacia abajo en lugar del flujo horizontal. En Job 36:28 las nubes ''derraman'' abundantemente, e Isaías 45:8 extiende esto a los cielos derramando justicia. Este sentido destaca la cualidad de caída gravitacional, distinta de un lecho de arroyo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116952, 'spa', 'El causativo Hifil', 'El causativo Hifil: hacer que el agua fluya. Aparece una sola vez en Isaías 48:21, donde Dios hizo brotar corrientes de la roca para Israel en el desierto — un acto deliberado de provisión divina. La forma causativa marca esto como alguien obligando al agua a moverse, no agua fluyendo por naturaleza propia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116954, 'spa', 'Un goteo suave o destilación, usado figuradamente de la enseñanza de Moisés en s', 'Un goteo suave o destilación, usado figuradamente de la enseñanza de Moisés en su cántico de despedida: ''Destilará como rocío mi palabra'' (Dt 32:2). El verbo destilar capta la cualidad lenta, gota a gota, que distingue este sentido del torrente de un arroyo o del aguacero de la lluvia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116955, 'spa', 'Un anillo usado como adorno general donde la ubicación específica — nariz u orej', 'Un anillo usado como adorno general donde la ubicación específica — nariz u oreja — no se especifica o resulta contextualmente ambigua. Job 42:11 registra que cada uno de los consoladores de Job le dio un נֶזֶם de oro entre sus regalos de restauración, sin especificación anatómica. Oseas 2:13 menciona anillos junto con otras joyas que la esposa infiel llevaba para sus amantes. Proverbios 25:12 compara al sabio que reprende con un anillo de oro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116956, 'spa', 'Un aro nasal — un anillo de oro llevado a través o sobre la nariz, frecuentement', 'Un aro nasal — un anillo de oro llevado a través o sobre la nariz, frecuentemente dado como regalo de compromiso nupcial. Génesis 24 ofrece la escena fundacional: el siervo de Abraham coloca un נֶזֶם de oro en la nariz de Rebeca (Gn 24:22, 30, 47). Isaías 3:21 enumera los aros nasales entre las galas arrebatadas a las hijas de Sion, y Proverbios 11:22 lanza su mordaz comparación: un aro de oro en el hocico de un cerdo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116957, 'spa', 'Un pendiente — un aro de oro llevado en la oreja como adorno personal', 'Un pendiente — un aro de oro llevado en la oreja como adorno personal. La narrativa del becerro de oro es el contexto definitorio: Aarón ordena ''quitad los aros de oro que están en las orejas de vuestras mujeres'' (Éx 32:2-3). Génesis 35:4 vincula los pendientes con dioses extranjeros, cuando Jacob los recoge para enterrarlos. Jueces 8:24-26 señala que los ismaelitas llevaban pendientes de oro, y Ezequiel 16:12 los incluye en la investidura que Dios otorga a Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116965, 'spa', 'Sufrir o causar daño', 'Sufrir perjuicio, ser dañado o causar daño, en contextos tanto personales como políticos. Daniel 6:2 describe la integridad de Daniel mediante la forma participial: «no se halló pérdida en él». Esdras 4:13 advierte al rey que si Jerusalén es reconstruida, los ingresos reales se verán perjudicados. El versículo 4:15 presenta a Jerusalén como ciudad dañina y rebelde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116967, 'spa', 'Consagración reflexiva', 'Dedicarse o consagrarse a una deidad o propósito sagrado, ya sea legítimo o idolátrico. En Oseas 9:10, Israel se consagró a Baal-peor en un acto de devoción reflexiva. Levítico 22:2 y 15:31 aplican la misma raíz a la separación sacerdotal de lo santo. Zacarías 7:3 emplea el infinitivo absoluto para la abstinencia ritual en contexto de ayuno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116968, 'spa', 'Voto nazareo', 'Asumir o mantener un voto nazareo de abstinencia consagrada ante el SEÑOR. Las cinco apariciones se encuentran en la legislación de Números 6. El voto exige separación del vino (Nm 6:3), cabello sin cortar (6:5) y pureza ante los muertos (6:6). La expresión «para el SEÑOR» marca la orientación devocional de cada caso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116969, 'spa', 'Consagración nazarea, el estado de separación votiva dedicada al SEÑOR, concentr', 'Consagración nazarea, el estado de separación votiva dedicada al SEÑOR, concentrada en Números 6. Abarca el cabello sin cortar (v. 5), la abstención de impureza por contacto con cadáveres (vv. 7-9) y los ritos de conclusión (vv. 12-19). El término designa tanto el período como la condición de quien ha sido apartado para un propósito sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116970, 'spa', 'Corona o diadema física portada como insignia de autoridad real o sacerdotal', 'Corona o diadema física portada como insignia de autoridad real o sacerdotal. La placa de oro del sumo sacerdote se denomina ''el נֵזֶר de santidad'' (Éx 29:6; 39:30; Lv 8:9), y la corona real aparece en 2 Samuel 1:10, 2 Reyes 11:12 y en los Salmos (89:40; 132:18). Zacarías 9:16 habla de ''piedras de corona'' que adornan a los redimidos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116976, 'spa', 'El nombre propio Noe (noakh, relacionado con nuakh ''descanso''), referido exclusi', 'El nombre propio Noe (noakh, relacionado con nuakh ''descanso''), referido exclusivamente al patriarca antediluviano que hallo gracia ante Dios, construyo el arca y fue el unico superviviente a traves del cual se preservo la humanidad (Gn 6:8-9:29). Su ubicacion genealogica como decimo desde Adan (Gn 5:29-32) y padre de Sem, Cam y Jafet lo convierte en el puente entre las epocas primigenia y posdiluviana. Fuera del Genesis, Ezequiel lo agrupa con Daniel y Job como paradigmas de justicia individual (Ez 14:14, 20), e Isaias usa ''las aguas de Noe'' como sinonimo del diluvio mismo (Is 54:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116982, 'spa', 'El sentido dominante', 'El sentido dominante: guiar o conducir a alguien por un camino, ruta o modo de vida, frecuentemente con Dios como sujeto. Dios guió a Israel por el desierto (Éx 13:17, 21), los condujo a su santa morada (Éx 15:13) y los pastoreó de la mano de Moisés y Aarón (Sal 77:20). Los Salmos aplican esto a la petición individual: «guíame por senda llana» (Sal 27:11), «guíame en tu verdad» (Sal 25:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (116997, 'spa', 'Un sentido extendido de asentar o estacionar personas en un destino después de c', 'Un sentido extendido de asentar o estacionar personas en un destino después de conducirlas allí. Salomón «colocó» carros en las ciudades de carros (1 R 10:26), y el rey de Asiria «asentó» a los cautivos israelitas en ciudades extranjeras (2 R 18:11). El énfasis se desplaza del viaje a su punto final: ubicación y habitación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117003, 'spa', 'Una única aparición en el oráculo de Balaam (Nm 23', 'Una única aparición en el oráculo de Balaam (Nm 23:7), donde Balac «me trajo» desde Aram. El versículo emplea el verbo en un contexto de convocatoria de un profeta a un lugar específico con un propósito determinado. El sentido es cercano al sentido 1, pero teñido por el tono coercitivo de un rey que recluta a un vidente, y por la ironía más amplia del pasaje: Balac lleva a Balaam para maldecir, pero Dios lleva a Balaam a bendecir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117014, 'spa', 'Consuelo y compasión', 'Consuelo, consolación o compasión. Isaías 57:18 promete restauración: «lo sanaré; lo guiaré y le restituiré consuelo a él y a sus enlutados», consolación divina tras la disciplina. Oseas 11:8 expresa la angustia de Dios: «Mi corazón se conmueve dentro de mí; se enciende toda mi compasión», un movimiento interior de misericordia. Zacarías 1:13 registra: «el SEÑOR respondió al ángel con palabras buenas, palabras consoladoras».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117016, 'spa', 'Nombre propio que identifica a dos figuras en la genealogía patriarcal', 'Nombre propio que identifica a dos figuras en la genealogía patriarcal: (1) el abuelo de Abraham, hijo de Serug (Gn 11:22-25; 1 Cr 1:26), y (2) el hermano de Abraham, hijo de Taré, cuyos descendientes incluyen a Rebeca y Labán (Gn 22:20-23; 24:15, 47). La ''ciudad de Nacor'' (Gn 24:10) sitúa a la familia en la alta Mesopotamia. Notablemente, Labán invoca al ''Dios de Nacor'' como deidad ancestral distinta en el pacto de Mizpa (Gn 31:53).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117021, 'spa', 'bronce, cobre (metal)', 'Cobre o bronce como metal, empleado exclusivamente en lenguaje poético y elevado. Literalmente designa el cobre fundido de la roca (Job 28:2) y el bronce como material para armas como arcos (2 Sam 22:35 = Sal 18:35) y puertas (Isa 45:2). Figuradamente connota fuerza inmensa (Job 40:18, huesos de behemot), agresión invencible (Miq 4:13, cascos de Sion), obstinación tenaz (Isa 48:4, frente de bronce) y juicio divino implacable (Lev 26:19, cielo de bronce).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117028, 'spa', 'El sentido central del Qal', 'El sentido central del Qal: recibir o heredar propiedades, tierras o una porción como concesión hereditaria. Cubre tanto los pasajes fundacionales de la promesa — ''tu descendencia la heredará'' (Éx 32:13) — como las asignaciones tribales concretas. El árabe waritha (forma I) confirma el significado receptivo simple, mientras que el coreano emplea 상속하다 (''heredar'') y el español heredar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117029, 'spa', 'El Hitpael reflexivo-recíproco', 'El Hitpael reflexivo-recíproco: tomar posesión para sí mismo, poseer como propio, o repartir una herencia entre sí. Se encuentra en contextos legales y administrativos: las tribus ''poseyendo para sí mismas'' dentro de Canaán (Nm 33:54; 34:13) y la regla de posesión perpetua de Levítico 25:46. El francés avoir hérité y el alemán sich erben captan el matiz reflexivo de autoposesión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117031, 'spa', 'El Hifil causativo', 'El Hifil causativo: dar a alguien una herencia, hacer poseer, otorgar tierra como concesión hereditaria. Concentrado en los discursos de Moisés en Deuteronomio (Dt 1:38; 3:28; 12:10; 19:3; 21:16), donde Moisés comisiona a Josué para ''hacer heredar'' la tierra a Israel. La forma IV árabe awratha (''hacer que alguien herede'') refleja exactamente la morfología hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117035, 'spa', 'El Piel factitivo', 'El Piel factitivo: repartir, distribuir o parcelar una herencia entre los beneficiarios. Se distingue del Hifil por centrarse en el acto administrativo de dividir más que en el de otorgar. El árabe de forma II qassama (''dividir, distribuir'') confirma un matiz de reparto distinto de la concesión. Aparece especialmente en Números 34 (la distribución de la tierra).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117066, 'spa', 'Una única ocurrencia ambigua en Job 7', 'Una única ocurrencia ambigua en Job 7:3 donde Job lamenta que le han sido ''asignados'' meses de vacuidad. El matiz pasivo o estativo — recibir una porción que uno no eligió — lo distingue tanto del recibir activo como del distribuir activo. El español he heredado y el inglés ''I have been allotted'' captan esa cualidad involuntaria, semejante al destino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117075, 'spa', 'wadi, arroyo estacional', 'Wadi o arroyo estacional (~82x): la acepción predominante, que abarca wadis con nombre propio (Cedrón, Arnón, Besor, Escol, Zered) y cauces estacionales genéricos. Dt 2:13-14 narra el cruce del wadi Zered; 1 S 30:9-10 usa el arroyo Besor como punto de concentración. El árabe وادي y el francés torrent-de reproducen este sentido geográfico-hidrológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117077, 'spa', 'valle, barranco', 'Valle o barranco (~28x): el énfasis pasa del cauce al relieve que lo contiene — la depresión, garganta o cañada como accidente topográfico. Gn 26:17 sitúa a Isaac acampando ''en el valle de Gerar''; Nm 13:23-24 nombra el valle de Escol donde los espías cortaron el célebre racimo. El español valle y el alemán Tal confirman el enfoque topográfico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117081, 'spa', 'río, corriente perenne', 'Río o corriente perenne (~19x): un curso de agua continuo y mayor que un arroyo estacional, asociado a la abundancia y la bendición. Dt 8:7 promete ''tierra de arroyos de agua, de fuentes y manantiales''; Lv 11:9-10 lo emplea para hábitats de agua dulce. El árabe نَهْر (río) y el coreano 강/시내 distinguen este sentido del flujo estacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117084, 'spa', 'torrente, avenida', 'Torrente o avenida violenta (~11x): la crecida repentina y destructora que irrumpe por un wadi durante un aguacero, usada en símiles de poder arrollador. Sal 124:4 advierte ''el torrente nos habría arrastrado''; 2 S 22:5 / Sal 18:4 describen ''torrentes de destrucción''. El árabe سَيْل (torrent/riada) captura la fuerza súbita y peligrosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117139, 'spa', 'tierra o propiedad heredada', 'Territorio concreto o patrimonio recibido como posesión permanente — típicamente las tierras tribales y familiares repartidas en Canaán. Dominante en Números, Josué y Deuteronomio (Nm 27:7 ''dales posesión como heredad''; Jos 13:23 ''la herencia de los hijos de Rubén''). El español heredad/herencia, el francés héritage y el alemán Erbe convergen en este sentido patrimonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117146, 'spa', 'heredad como porción pactual', 'Herencia metafórica o pactual que expresa pertenencia relacional más que posesión de tierras. Dios declara a Israel ''mi heredad'' (Dt 4:20; 1 R 8:51), y el salmista responde que Dios mismo es ''mi porción y mi herencia'' (Sal 16:5-6). Este uso recíproco — Dios poseyendo a Israel, Israel poseyendo a Dios — constituye el núcleo teológico del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117194, 'spa', 'Gentilicio identificativo', 'Designación gentilicia que aparece exclusivamente en Jeremías 29, identificando al falso profeta Semaías que se opuso al mensaje de Jeremías a los exiliados en Babilonia. Las tres ocurrencias se concentran en los versículos 24-32, donde Jeremías condena a Semaías por enviar cartas no autorizadas reclamando autoridad divina. El término funciona como epíteto propio, posiblemente derivado de un lugar desconocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117195, 'spa', 'consolar, confortar (Piel)', 'Piel: consolar, confortar o animar a alguien que sufre. Sentido transitivo activo de brindar alivio emocional, dicho tanto de agentes humanos como divinos. José consuela a sus hermanos (Gn 50:21), Rut es consolada por las palabras de Booz (Rt 2:13) y Dios consuela a su pueblo (Is 40:1). Las lenguas convergen: español consolar, francés consoler, alemán trösten.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117199, 'spa', 'arrepentirse, desistir (Nifal)', 'Nifal: arrepentirse, cambiar de parecer o desistir de una acción planeada. Predicado casi siempre de Dios que se retracta de un juicio anunciado — ''YHWH se arrepintió del mal'' (Éx 32:14; Am 7:3, 6). También de humanos que lamentan decisiones (Gn 6:6-7). El español se arrepintió y el coreano 뉘우치다 captan este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117202, 'spa', 'ser consolado (Nifal pasivo)', 'Nifal medio-pasivo: ser consolado, recibir consuelo. El sujeto es quien recibe la consolación. Isaac ''fue consolado'' tras la muerte de Sara al llegar Rebeca (Gn 24:67); Raquel ''no quiso ser consolada'' por sus hijos (Jer 31:15). El español ser consolada, el francés être consolé y el alemán getröstet werden reflejan esta orientación pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117214, 'spa', 'consolarse, buscar consuelo (Hitpael)', 'Hitpael: consolarse a sí mismo, buscar consuelo. Reflexivo del Piel, donde el sujeto procura activamente su propia consolación. Esaú ''se consolaba'' con planes de venganza (Gn 27:42); Jacob rehusó dejarse consolar por José (Gn 37:35). El salmista encuentra consuelo al recordar los decretos antiguos de Dios (Sal 119:52). El español consolándose y el alemán sich trösten reflejan este matiz reflexivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117221, 'spa', 'ser consolado (Pual pasivo)', 'Pual: ser consolado — pasivo del Piel que indica que el sujeto recibe consuelo de un agente externo. Solo dos casos claros: ''Oh afligida, no consolada'' (Is 54:11) y la promesa ''seréis consolados en Jerusalén'' (Is 66:13). Se distingue del Nifal pasivo (acepción 3) por su morfología estrictamente pasiva, sin matiz reflexivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117227, 'spa', 'compadecerse, apiadarse', 'Tener compasión o ser movido a piedad — sentido emocional extendido en contextos Nifal e Hitpael, que expresa profunda simpatía o misericordia ante el sufrimiento. En Dt 32:36, YHWH ''se compadece de sus siervos''; los jueces que Dios levantó fueron impulsados porque Él ''se apiadaba'' (Jue 2:18). El árabe رَحِمَ y el español compadecerse distinguen este matiz del arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117277, 'spa', 'Nehemías (nombre propio)', 'Nombre propio נְחֶמְיָה que designa a tres individuos distintos: (a) el gobernador de Judá bajo Artajerjes que reconstruyó las murallas de Jerusalén e impulsó reformas religiosas (Neh 1:1; 8:9; 10:2; 12:26, 47), (b) un jefe de distrito que colaboró en la reparación de la muralla (Neh 3:16), y (c) un repatriado del exilio mencionado junto a Zorobabel (Esd 2:2 = Neh 7:7). El elemento teofórico -yah (''Yah consuela'') se refleja en todas las versiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117279, 'spa', 'Nosotros', 'Pronombre personal de primera persona del plural «nosotros», funcionalmente idéntico a אֲנַחְנוּ pero en forma más breve, posiblemente más antigua o dialectal. Sus cinco apariciones se dan en discurso directo emocionalmente intenso: autoidentificación colectiva (Gn 42:11), queja (Éx 16:7-8), compromiso militar (Nm 32:32) y confesión penitencial (Lm 3:42).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117284, 'spa', 'practicar adivinación', 'Practicar la adivinación o leer presagios como arte mántica, práctica categóricamente prohibida por la ley israelita. El Código de Santidad prohíbe el nachash junto a otras prácticas ocultas (Lev 19:26) y Deuteronomio condena al menachesh como abominación (Deut 18:10). Los reyes de Israel y Judá son acusados de cometer este pecado (2 Re 17:17; 21:6; 2 Cr 33:6). El verbo abarca diversas técnicas de lectura de señales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117294, 'spa', 'Bronce, cobre (arameo)', 'Bronce o cobre como material, específicamente la forma aramea empleada en las visiones apocalípticas de Daniel. El sustantivo describe la porción de bronce de la estatua compuesta (Dan 2:32, 35, 39, 45), las garras de bronce de la cuarta bestia (Dan 7:19) y las bandas de bronce y hierro sobre el tronco simbólico (Dan 4:15, 23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117296, 'spa', 'Serpiente o culebra, abarcando tanto el reptil literal como su rico rango simból', 'Serpiente o culebra, abarcando tanto el reptil literal como su rico rango simbólico. En Génesis 3:1-14 es el astuto tentador del Edén; en Números 21:6-9 aparece como la «serpiente ardiente» letal y luego como la imagen de bronce que sana. Amós 5:19 y Eclesiastés 10:8 la usan para el peligro mortal súbito. Isaías 27:1 la extiende a una figura cósmica de monstruo marino. Todas las apariciones comparten la imagen central de amenaza primordial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117306, 'spa', 'Najás (nombre propio)', 'Nombre propio masculino que designa principalmente al rey amonita cuyo asedio de Jabes de Galaad catalizó la monarquía de Saúl (1 Sam 11:1-2; 12:12). El mismo Najás o un sucesor mantuvo relaciones con David (2 Sam 10:2; 1 Cr 19:1-2; posiblemente 2 Sam 17:27). Un Najás distinto aparece como progenitor de las hermanas de David (2 Sam 17:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117308, 'spa', 'Naasón (nombre propio)', 'El nombre propio Naasón (quizá ''pequeña serpiente'' o derivado de nachash), que designa al príncipe de Judá durante el período del desierto. Aparece en el censo sacerdotal y las listas de marcha (Nm 1:7; 2:3; 10:14), ofreció los dones inaugurales de dedicación del tabernáculo (Nm 7:12-17) y era cuñado de Aarón (Éx 6:23). Los textos genealógicos de Rut 4:20-22 y 1 Crónicas 2:10-11 lo anclan en la línea directa hacia David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117312, 'spa', 'bronce/cobre como metal', 'El metal bronce o cobre en todas sus aplicaciones — mineral extraído de la tierra (Dt 8:9), material refinado para vasos sagrados y revestimientos arquitectónicos (Éx 26:11; 1 R 7:45), y símbolo de fuerza o terquedad. Las traducciones multilingües convergen en un solo término metalúrgico (bronce, Bronze), confirmando esta acepción nuclear e indiferenciada que cubre 131 de las 139 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117316, 'spa', 'grillos de bronce', 'La forma dual נְחֻשְׁתַּיִם designa un par de grillos de bronce para aprisionar cautivos. Las ocho apariciones describen encadenamiento — Sansón en Gaza (Jue 16:21), Sedequías por Nabucodonosor (2 R 25:7), Manasés en cautiverio asirio (2 Cr 33:11). El español con bronces capta la metonimia donde el material representa el instrumento de sujeción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117336, 'spa', 'descender, bajar', 'Sentido básico del Qal de descender o bajar, ya sea física o figuradamente. En Jer 21:13 describe un ataque que desciende sobre un objetivo; en Job 21:13, los impíos descienden al Seol rápidamente. En Prov 17:10, una reprensión «penetra más» en el prudente que cien azotes en el necio, resaltando la penetración figurada de este movimiento descendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117338, 'spa', 'presionar, doblegar', 'Forma intensiva Piel que significa presionar hacia abajo, doblegar o hacer asentar bajo peso o fuerza. En 2 Sam 22:35 y Sal 18:34, Dios adiestra los brazos del guerrero para que puedan doblegar un arco de bronce, imagen de fuerza sobrenatural que somete un metal inflexible. En Sal 65:10, Dios asienta los surcos de la tierra con la lluvia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117339, 'spa', 'clavarse, hundirse', 'Sentido pasivo del Nifal de hundirse o ser clavado en algo, como proyectiles fijados en un blanco. En Sal 38:2, las flechas de Dios «se han clavado» en el salmista, imagen estremecedora de la disciplina divina experimentada corporalmente. El español «se clavaron» transmite vívidamente la fuerza de esta penetración pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117341, 'spa', 'hacer descender', 'Sentido causativo del Hifil de hacer bajar o causar el descenso desde lo alto. En Joel 3:11 (4:11 en hebreo), el profeta invoca a Dios para que haga descender a sus guerreros, una petición de intervención divina que desciende del cielo a la tierra. Es la forma atestiguada más rara, con una sola ocurrencia clara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117342, 'spa', 'ser quebrantado', 'Sentido distinto del Nifal que significa ser quebrantado o destrozado, presente en el cántico de Ana (1 Sam 2:10) donde los adversarios del Señor «serán quebrantados». Algunos eruditos lo conectan con una raíz diferente (hathath, quebrantar), pero la tradición textual y las versiones antiguas lo asocian con el campo semántico de la fuerza descendente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117346, 'spa', 'Descender, bajar', 'Descender o bajar desde lo alto (Peal, equivalente al Qal hebreo). Usado exclusivamente en la visión de Daniel del vigía divino ''descendiendo del cielo'' (Dn 4:13, 23). El árabe ''nazala'' (descender) es el cognado más cercano. El uso transmite la gravedad teofánica de un ser celestial que baja a la tierra para ejecutar el decreto divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117347, 'spa', 'Depositar, colocar', 'Depositar, colocar o almacenar en un lugar designado (causativo Hafel). En Esdras 6:1 el participio pasivo describe registros reales ''depositados'' en la casa del tesoro babilónico; Esdras 5:15 y 6:5 ordenan que los utensilios del templo sean llevados y colocados de vuelta en el santuario de Jerusalén. El registro es burocrático-administrativo, propio de documentos oficiales del imperio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117349, 'spa', 'Ser depuesto', 'Ser depuesto o derribado de una posición de autoridad (pasivo Hofal). Daniel 5:20 declara que cuando el corazón de Nabucodonosor se enalteció en orgullo, ''fue depuesto de su trono real''. El pasivo causativo transforma el descenso físico en caída política. La raíz extiende su significado espacial a la pérdida del poder soberano, vinculando soberbia con derrocamiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117351, 'spa', 'Reposo, quietud, tranquilidad', 'Estado de quietud, descanso o tranquilidad apacible, contrapuesto deliberadamente a la agitación, el afán o la lucha insensata. En Isaías 30:15 נַחַת se empareja con הַשְׁקֵט como los dos pilares de la salvación de Israel: confianza serena en lugar de alianzas frenéticas. Eclesiastés 4:6 contrasta célebremente ''un puñado de reposo'' con dos puñados de trabajo y persecución del viento. Proverbios 29:9 lo usa como opuesto de la furia y la risa burlona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117356, 'spa', 'Jefe edomita', 'Najat hijo de Reuel, nieto de Esaú, jefe de clan edomita. Aparece en las genealogías edomitas de Génesis 36:13, 17 y 1 Crónicas 1:37. La Septuaginta transcribe el nombre como Nachoth o Nacheth. La forma española «Najat» conserva la consonante gutural inicial del hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117357, 'spa', 'Que desciende', 'Participio masculino plural que funciona como adjetivo en 2 Reyes 6:9, posiblemente con el sentido de ''que descienden'' o ''que bajan''. La frase en contexto es: ''Guárdate de pasar por tal lugar, porque los arameos descienden allí.'' Sin embargo, el texto hebreo es incierto; la Septuaginta lee ''escondidos/al acecho'' (sugiriendo נֶחְבִּים de חָבָא), lectura que muchos eruditos prefieren.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117358, 'spa', 'brazo extendido (participio Qal)', 'Participio pasivo Qal ''extendido'' (30x): estado de extensión, casi exclusivamente referido al ''brazo extendido'' de Dios (זְרוֹעַ נְטוּיָה), expresión fija para el poder redentor. Fórmula deuteronómica: ''con mano poderosa y brazo extendido'' (Dt 4:34, 5:15, 7:19, 9:29, 11:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117359, 'spa', 'extender mano/brazo (Qal)', 'Qal ''extender mano/brazo'' (45x): extensión física, sobre todo Dios o Moisés extendiendo la mano en juicio o prodigio. Concentrado en las plagas de Egipto (Éx 7:5, 7:19, 8:5-6, 8:16) y la conquista (Jos 8:18-19, 26). El ''brazo extendido'' se convierte en motivo teológico del poder divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117363, 'spa', 'inclinar oído/corazón (Hifil)', 'Hifil ''inclinar oído/corazón'' (37x): sentido causativo-metafórico de dirigir la atención o la devoción hacia Dios, la instrucción o la sabiduría. Ejemplos clásicos: ''Inclina tu oído y oye'' (2 R 19:16), ''inclina tu corazón a YHWH'' (Jos 24:23). El español inclinar y el árabe أَمَالَ distinguen este uso del estiramiento físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117366, 'spa', 'armar una tienda (Qal)', 'Qal ''armar una tienda'' (10x): aplicación concreta de levantar una tienda o tabernáculo al extender su tela. Los patriarcas ''armaron su tienda'' (Gn 12:8, 26:25, 33:19, 35:21), Moisés ''armó la tienda de reunión'' (Éx 33:7). El verbo se extiende naturalmente de ''estirar'' a ''erigir una estructura tensada''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117369, 'spa', 'pervertir la justicia (Hifil)', 'Hifil ''pervertir la justicia'' (14x): especialización moral de torcer o distorsionar el derecho. En contextos legales: ''No pervertirás el derecho'' (Éx 23:6, Dt 16:19, 24:17, 27:19). También 1 S 8:3 (''sus hijos torcieron la justicia''), Pr 17:23, Am 5:12. Las traducciones diferencian con fuerza este uso del mero desvío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117372, 'spa', 'inclinarse, declinar (Qal)', 'Qal intransitivo ''inclinarse, declinar'' (16x): inclinación física sin objeto — las sombras que declinan (Jue 19:8), Isacar que dobla el hombro (Gn 49:15), Sansón que se inclina con toda su fuerza (Jue 16:30). Incluye a Dios inclinando su misericordia hacia José (Gn 39:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117375, 'spa', 'apartarse, desviarse (Qal)', 'Qal intransitivo ''apartarse'' (24x): desviarse de un camino o una norma, sin objeto directo. Judá ''se apartó'' hacia Timnat (Gn 38:1, 38:16), Israel ''no se desvió'' del camino (Nm 20:17, 21). Desviación moral en Éx 23:2, 1 S 8:3, Sal 73:2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117376, 'spa', 'desviar, apartar (Hifil)', 'Hifil causativo ''desviar'' (21x): hacer que alguien o algo se aparte — extraviar, desviar de un camino. La burra de Balaam ''se desvió'' (Nm 22:23), David ''hizo volver'' el arca a casa de Obed-edom (2 S 6:10). El contexto suele implicar intencionalidad o liderazgo (2 S 3:27, 16:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117382, 'spa', 'desplegar los cielos (participio)', 'Participio activo Qal ''el que extiende (los cielos)'' (12x): Dios como quien despliega las estructuras cósmicas — imagen de tienda para la creación. Concentrado en Job (9:8, 26:7) e Isaías (40:22, 42:5, 44:24, 45:12, 51:13). ''El que extiende los cielos'' (נֹטֶה שָׁמַיִם) se convierte en epíteto divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117386, 'spa', 'desplegar, extender (Qal finito)', 'Qal finito ''desplegar, extender'' (7x): se solapa con la acepción 1 pero enfatiza la extensión cósmica o territorial — Dios ''extendió los cielos'' (Is 45:12, Jer 10:12), los valles ''se extienden'' (Nm 24:6), las sombras ''se alargan'' (Jer 6:4). Se distingue del participio (acepción 8) por la forma verbal finita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117497, 'spa', 'Cargado de', 'Adjetivo participial plural constructo que significa ''cargados de, que llevan, que portan'' en Sofonías 1:11. La frase ''los cargados de plata'' (נְטִילֵי כָסֶף) identifica a comerciantes adinerados que serán destruidos en el juicio venidero de Dios sobre Jerusalén. La palabra sugiere estar cargado o agobiado por el peso, aquí el peso de la plata. La raíz נטל aparece en hebreo tardío con el significado de ''tomar, levantar, cargar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117499, 'spa', 'Sarmientos de vid', 'Sarmientos o ramas extendidas de una vid. Isaías 18:5 describe el juicio: antes de la cosecha, Dios corta los brotes con podaderas y elimina las ramas que se extienden. Jeremías 5:10 ordena a los destructores arrancar los sarmientos de la viña. Jeremías 48:32 los usa metafóricamente para la prosperidad de Moab, cuyos sarmientos cruzaban el mar, representando una influencia vasta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117500, 'spa', 'Levantar y cargar', 'Levantar, cargar o llevar, usado en contextos poéticos y proféticos. Isaías 40:15 declara que Dios «levanta las costas como polvo fino», alzando islas como si fueran partículas sin peso. Isaías 63:9 describe el amor redentor de Dios que cargó y llevó a su pueblo con compasión. El verbo enfatiza el sostener continuo de un peso, más que un gesto momentáneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117502, 'spa', 'Peso o carga', 'Sustantivo masculino constructo que significa ''peso, carga'' en Proverbios 27:3. El versículo dice: ''Pesada es la piedra y la arena pesa (lit.: ''y la carga de la arena''), mas la ira del necio es más pesada que ambas.'' La palabra נֵטֶל se usa en paralelo con כֹּבֶד (pesadez, peso), ambos subrayando la carga física. El proverbio emplea peso tangible y mensurable para expresar la carga mucho mayor de soportar la provocación de un necio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117503, 'spa', 'El sentido agrícola literal', 'El sentido agrícola literal: plantar árboles, vides, huertos u otra vegetación en la tierra. Es el uso dominante en toda la Biblia hebrea, desde que Dios plantó el Jardín del Edén (Gn 2:8) y Noé plantó la primera viña (Gn 9:20), pasando por las leyes sobre árboles frutales recién plantados (Lv 19:23), hasta las promesas proféticas de plantar viñas y comer de su fruto (Am 9:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117510, 'spa', 'Una extensión metafórica', 'Una extensión metafórica: plantar o establecer firmemente a un pueblo en un lugar, especialmente cuando Dios asienta a Israel en la Tierra Prometida. La imagen transfiere el arraigo de un árbol plantado a la seguridad de una nación asentada. Dios ''los plantó'' en el cántico del Sinaí (Éx 15:17), prometió a David que ''plantaría'' a Israel para que habitaran sin perturbación (2 S 7:10; 1 Cr 17:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117525, 'spa', 'Un sentido extendido poco frecuente', 'Un sentido extendido poco frecuente: clavar, hincar o fijar firmemente en su lugar — aplicado a objetos no vegetales. En Ec 12:11, las palabras de los sabios son como clavos ''plantados'' (firmemente hincados), y en Dn 11:45, un rey ''planta'' sus tiendas palatinas entre los mares. La idea básica de introducir algo en la tierra persiste, pero el objeto es una estaca, clavo o tienda en vez de una planta viva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117544, 'spa', 'Plantación o plantío', 'Plantación, plantío o planta, frecuentemente con significado metafórico. Isaías 5:7 interpreta la parábola de la viña: «los hombres de Judá son su plantío predilecto», el pueblo deliberadamente cultivado por Dios. Isaías 17:10 condena la idolatría: «plantas plantíos agradables», cultivando adoración ajena en vez de verdadera devoción. Job lo emplea como imagen de renovación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117545, 'spa', 'Plantas o brotes', 'Sustantivo masculino plural que significa ''plantas, plantíos'' en Salmo 144:12, usado en sentido figurado. El versículo ora: ''Sean nuestros hijos como plantas crecidas en su juventud,'' comparando a los jóvenes con plantas o retoños bien desarrollados. La imagen sugiere fuerza, salud y promesa: plantas jóvenes que han crecido exitosamente representan la vigorosa nueva generación. Esta metáfora agrícola se complementa con la imagen siguiente de las hijas como columnas talladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117546, 'spa', 'Topónimo en Judá', 'Nombre de lugar en 1 Crónicas 4:23, aparentemente un asentamiento en Judá donde moraban alfareros reales. El texto describe a estos residentes como ''alfareros que habitaban en Netaim y Guederá; allí vivían con el rey para su obra.'' El nombre נְטָעִים deriva de la raíz נטע (plantar), posiblemente con el significado de ''plantíos'' o ''lugares con jardines''. Los manuscritos griegos antiguos variaron en su transcripción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117547, 'spa', 'Goteo físico intransitivo de líquido en el Qal', 'Goteo físico intransitivo de líquido en el Qal: lluvia de las nubes, mirra de las manos, miel de los labios. Jueces 5:4 describe nubes goteando agua durante la teofanía sinaítica, mientras que Cantar de los Cantares 4:11 y 5:13 lo usan para la mirra y el panal. El verbo capta la cualidad lenta, gota a gota, del destilado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117548, 'spa', 'Sentido figurado del Hifil que significa profetizar o predicar, literalmente hac', 'Sentido figurado del Hifil que significa profetizar o predicar, literalmente hacer que las palabras gotéen. Esta metáfora casi siempre conlleva matices hostiles: Amós 7:16 registra al sacerdote Amasías ordenando a Amós que no ''gotée'' contra Israel, y Miqueas 2:6 cita a los opositores diciendo ''no profeticéis''. El salto semántico del líquido al discurso marca un uso figurado nítido de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117558, 'spa', 'Una única aparición del Hifil que conserva el sentido físico literal en un marco', 'Una única aparición del Hifil que conserva el sentido físico literal en un marco causativo: las montañas haciendo destilar vino dulce en la abundancia escatológica de Amós 9:13. Aunque gramaticalmente es Hifil como el sentido 2, el significado no es discurso profético sino superabundancia agrícola, siendo los mismos montes agentes del fluir del líquido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117565, 'spa', 'Netofatita (gentilicio)', 'Gentilicio que designa a un nativo o habitante de Netofá, aldea judía cercana a Belén. Identifica a guerreros de élite en la guardia de David —Maharai y Heleb/Heled el netofatita (2 Sam 23:28-29; 1 Cr 11:30; 27:13, 15)— así como a oficiales militares que se reunieron con Gedalías tras la destrucción de Jerusalén (2 Re 25:23; Jer 40:8). Los registros postexílicos asocian a los netofatitas con cantores levitas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117570, 'spa', 'Guardar, custodiar, vigilar', 'Guardar, custodiar o vigilar algo encomendado al cuidado de uno, particularmente viñas. Cantar de los Cantares 1:6 ofrece la memorable confesión: ''me pusieron a guardar las viñas, pero mi propia viña no guardé'', donde el verbo repetido crea un contraste conmovedor entre el deber hacia otros y el descuido propio. Cantares 8:11-12 usa la forma participial para guardas de viñas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117571, 'spa', 'Guardar rencor, mantener ira', 'Guardar rencor, mantener la ira o albergar enojo a lo largo del tiempo. Levítico 19:18 ordena ''no guardarás rencor'' junto al célebre mandamiento de amar al prójimo. Jeremías 3:5 y 3:12 preguntan si Dios ''guardará enojo para siempre'', mientras que Nahúm 1:2 afirma que el SEÑOR ''guarda ira'' para sus adversarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117579, 'spa', 'Esparcirse, desplegarse o ser dispersado sobre un área', 'Esparcirse, desplegarse o ser dispersado sobre un área: seis apariciones concentradas en los relatos militares de Jueces y Samuel. Los filisteos «se desplegaron en el valle de Refaím» (2 S 5:18, 22), las fuerzas de Judá «se desplegaron» en Lehí (Jue 15:9), y los saqueadores se hallaron «esparcidos por toda la tierra» (1 S 30:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117580, 'spa', 'El sentido relacional dominante', 'El sentido relacional dominante: abandonar, desamparar o dejar atrás deliberadamente a una persona, pueblo o vínculo de alianza. Veintitrés de cuarenta apariciones llevan este significado. En Gn 31:28 Labán acusa a Jacob de no haberle dejado besar a sus nietos; en Jue 6:13 Gedeón protesta que Yahvé ha abandonado a Israel; en 1 S 12:22 Samuel asegura que Dios no abandonará a su pueblo «por su gran nombre».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117581, 'spa', 'Arrojar, derribar o lanzar como acto de rechazo violento o castigo divino', 'Arrojar, derribar o lanzar como acto de rechazo violento o castigo divino: seis apariciones, mayormente en los oráculos de juicio de Ezequiel. Dios «arrojará» a Faraón al desierto (Ez 29:5), el gran cedro es «derribado» y sus ramas «caen» en cada valle (Ez 31:12). La direccionalidad violenta y descendente distingue este sentido del «abandonar» relacional del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117585, 'spa', 'Un sentido más leve y no relacional', 'Un sentido más leve y no relacional: dejar en paz, dejar estar o cesar la participación. En 1 S 17:28 Saúl pregunta con quién «dejó» David las ovejas; en Pr 17:14 la sabiduría aconseja «abandonar» la contienda antes de que escale; en Os 12:14 el sentido es dejar las consecuencias en su lugar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117591, 'spa', 'Un uso único en Isaías 33', 'Un uso único en Isaías 33:23 que describe cuerdas que «se soltaron» o «se aflojaron» en el mástil de un barco. La imagen de una embarcación inutilizada sugiere aflojamiento físico: cuerdas liberadas de la tensión. Puede ser una extensión especializada de la metáfora raíz de «soltar» aplicada al aparejo náutico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117602, 'spa', 'Una única aparición en Isaías 21', 'Una única aparición en Isaías 21:15 donde el participio pasivo femenino describe una espada «desenvainada», es decir, una espada que ha sido «soltada» de su vaina. El contexto militar de huida de la batalla confirma este sentido como una «liberación» concreta y física de un arma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117615, 'spa', 'Cualidad apaciguante o agradable atribuida a los aromas sacrificiales', 'Cualidad apaciguante o agradable atribuida a los aromas sacrificiales. Ligado casi exclusivamente a la fórmula רֵיחַ נִיחוֹחַ (Gn 8:21; Éx 29:18; Lv 1:9 y más de 30 textos sacerdotales), transmitiendo que la ofrenda «apacigua» el desagrado divino. En Números 28:2, Dios lo personaliza: נִיחוֹחִי, «mi aroma apaciguante». Las traducciones convergen en «agradable» o «grato».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117624, 'spa', 'Descendencia inmediata', 'Descendencia o progenie, posteridad inmediata. Génesis 21:23 registra el juramento que Abimelec solicita a Abraham, cubriendo todas las generaciones futuras. Job 18:19 describe la suerte del malvado: sin descendencia ni posteridad entre su pueblo. Isaías 14:22 profetiza contra Babilonia la eliminación total de toda generación futura, sin que quede sobreviviente alguno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117625, 'spa', 'Nombre propio de la capital asiria, que aparece en Génesis 10', 'Nombre propio de la capital asiria, que aparece en Génesis 10:11-12 como fundada en la historia primordial, en 2 Reyes 19:36 e Isaías 37:37 como residencia real de Senaquerib, y de manera más prominente en Jonás y Nahúm como objeto de advertencia profética y condenación. Las traducciones en todas las lenguas transliteran uniformemente como ''Nínive/Ninive'', confirmando su reconocimiento universal como topónimo fijo del mundo antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117632, 'spa', 'Barbecho o tierra sin labrar', 'Barbecho, tierra sin labrar o en desuso que necesita cultivo. Oseas 10:12 ordena metafóricamente: «Roturad vuestro barbecho», instando a Israel a una receptividad espiritual renovada en lugar de continuar en rebelión endurecida. Jeremías 4:3 emplea la misma imagen: «Arad vuestro barbecho y no sembréis entre espinos», preparando el terreno interior antes de recibir la palabra divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117633, 'spa', 'Lámpara de aceite literal o conjunto de lámparas, particularmente las lámparas d', 'Lámpara de aceite literal o conjunto de lámparas, particularmente las lámparas doradas del candelabro del tabernáculo (Éx 25:37; 30:7-8) y los utensilios del templo (1 R 7:49; 2 Cr 4:20). También se usa para el candelabro visionario de Zacarías (Zac 4:2) y las lámparas domésticas (Pr 31:18). El referente es un artefacto concreto de iluminación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117636, 'spa', 'Lámpara usada metafóricamente para la fuerza vital, la prosperidad, la continuid', 'Lámpara usada metafóricamente para la fuerza vital, la prosperidad, la continuidad dinástica o la guía divina. David es «la lámpara de Israel» (2 S 21:17); Dios enciende la lámpara del salmista (2 S 22:29 / Sal 18:28); la lámpara de los impíos se apaga (Job 18:6; Pr 24:20). El contexto hebreo pasa enteramente del artefacto al símbolo de vitalidad y promesa de alianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117652, 'spa', 'Lámpara dinástica', 'Lámpara usada figuradamente para la continuidad dinástica o la bendición. 1 Reyes 11:36 explica por qué Dios no retira todo el reino a Salomón: «para que David mi siervo tenga siempre una lámpara ante mí en Jerusalén», asegurando la presencia davídica en el trono. 1 Reyes 15:4 señala que Dios dio un hijo a Abías para «levantar una lámpara para David», continuando la dinastía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117655, 'spa', 'Espíritu quebrantado', 'Quebrantado o abatido, específicamente del espíritu. Proverbios 15:13 enseña que la tristeza del corazón quebranta el espíritu. Proverbios 17:22 contrasta el corazón gozoso con el espíritu quebrantado que seca los huesos, mostrando cómo la devastación interior afecta la salud física. Proverbios 18:14 pregunta quién puede soportar un espíritu quebrantado, reconociendo su peso insoportable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117657, 'spa', 'Posteridad y nietos', 'Posteridad o nietos, descendientes de generaciones posteriores. Génesis 21:23 registra la petición de Abimelec cubriendo hijos y nietos. Job 18:19 declara que el malvado no tiene descendencia ni posteridad entre su pueblo: ni hijos ni nietos sobreviven. Isaías 14:22 amenaza a Babilonia con cortar toda descendencia y posteridad, asegurando que ninguna generación futura permanezca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117658, 'spa', 'herir en batalla (Hifil)', 'El Hifil militar principal (362x) domina los relatos bélicos de la Escritura. Moisés ''hirió a Egipto con todas sus plagas'' (Éx 7:20, 8:17, 9:25), Josué ''hirió a los cananeos'' (Jos 10:28-40), David ''hirió a los filisteos'' (2 S 5:20, 8:1). Todas las lenguas emplean un verbo genérico de golpe: español herir/golpear, coreano 치다, árabe ضَرَبَ.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117665, 'spa', 'golpear un objeto (Hifil)', 'Golpear objetos inanimados (14x): tierra, ciudad, agua, roca. ''Heriré las aguas del Nilo'' (Éx 7:17), ''golpearás la roca'' (Éx 17:6), ''Josué tomó la tierra'' (Jos 10:28, 30). Los sufijos pronominales femeninos y el neutro inglés ''it'' marcan el complemento inanimado. Se distingue de las acepciones con objeto personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117666, 'spa', 'matar, dar muerte (Hifil)', 'Golpe letal (21x) donde el impacto resulta en muerte. ''El que hiera a Caín, siete veces será vengado'' (Gn 4:15), ''matémoslo'' (Gn 37:21, lit. ''hirámoslo de muerte''). El español emplea matar, el coreano 죽이다, el árabe يَقْتُل. Las traducciones marcan explícitamente la muerte como resultado, distinguiendo esta acepción de la herida no letal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117668, 'spa', 'derrotar, vencer (Hifil)', 'Sentido figurado o militar de ''derrotar, vencer'' (18x), que enfatiza la conquista sobre el mero golpe. ''Abraham los derrotó'' (Gn 14:17), ''los destruirás del todo'' (Dt 7:2), ''el que conquiste Quiriat-séfer'' (Jos 15:16). El español usa vencer/derrotar, el coreano 이기다. El énfasis recae en la victoria, no en el impacto físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117674, 'spa', 'herir, lesionar (Hifil)', 'Herir sin matar (5x), concentrado en relatos de conspiraciones regias. ''Lo hirieron'' (2 R 8:29, 9:15, hiriendo al rey Joram), ''los siervos hirieron y mataron a Joás'' (2 R 12:21). El árabe cambia a جَرَحَ (herir) en vez del habitual ضَرَبَ. El contexto muestra lesión sin muerte inmediata, generando tensión narrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117676, 'spa', 'afligir con plaga (Hifil)', 'Aflicción divina con plaga o maldición (19x). ''Te heriré con tizón, añublo y granizo'' (Dt 28:22, 27, 28, 35), ''YHWH hirió al pueblo con gran plaga'' (Nm 11:33). El sujeto es Dios y el complemento es enfermedad o maldición, lo que distingue claramente esta acepción del golpe humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117681, 'spa', 'ser golpeado, herido (Hofal)', 'Hofal pasivo ''ser golpeado, herido'' (16x): el estado del receptor. ''Los capataces de los hijos de Israel fueron azotados'' (Éx 5:14, 16), ''es hallado forzando y es herido de modo que muera'' (Éx 22:2). El español fue golpeada/herido, el coreano 맞다. El participio Hofal describe a quienes han sufrido el impacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117689, 'spa', 'golpear, azotar (Hifil)', 'Golpes físicos no letales (35x): azotar, pegar o castigar a personas fuera de la guerra. ''Si un hombre golpea a su siervo con vara'' (Éx 21:20), ''Moisés vio a un egipcio golpeando a un hebreo'' (Éx 2:11). El coreano cambia a 때리다 (pegar), el español usa azotar/golpear. Se distingue por la proximidad personal y la ausencia de muerte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117691, 'spa', 'ser golpeado, Pual', 'Dos apariciones Pual pasivas (Éx 9:31-32) en el relato de la plaga de granizo: ''El lino y la cebada fueron destruidos'' por el granizo. El español fueron golpeados, el coreano 맞았다. El raro Pual marca la recepción pasiva del impacto del granizo sobre los cultivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117727, 'spa', 'golpear (condición futura)', 'Balac a Balaam: ''Quizá pueda yo herirlos'' (Nm 22:6, 1x). El español golpear, el coreano 치다. Construcción condicional en la que Balac espera derrotar a Israel mediante los oráculos de Balaam — una derrota militar deseada por medios mágicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117752, 'spa', 'echar raíces (metáfora)', '''Echará raíces como el Líbano'' (Os 14:5, 1x). El español echar (lanzar/producir), el coreano 내리다 (hacer descender). Metáfora agrícola única donde ''golpear raíz'' significa arraigar, afianzarse. La imagen es de crecimiento y estabilidad, no de violencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117772, 'spa', 'ser herido (Nifal pasivo)', 'Nifal pasivo: ''Será herido y morirá'' (2 S 11:15, 1x, la orden de David contra Urías). El español será herido, el coreano 맞아 죽다. Única aparición Nifal en construcción pasiva, donde Urías es receptor pasivo del golpe letal en batalla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117802, 'spa', 'meter, clavar (culinario)', 'El criado de Elí ''metía'' el tenedor en la olla, la caldera o la sartén (1 S 2:14, 1x). El español meter, el coreano 찌르다 (hincar/clavar). Contexto culinario único donde golpear significa hundir el instrumento en los recipientes para extraer carne sacrificial, con oscura ironía dada la corrupción de los hijos de Elí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117828, 'spa', 'batir palmas (Hifil)', 'Batir palmas (4x), extensión metafórica. ''Batí mis manos de ira'' (Ez 22:13), ''batieron palmas'' (2 R 11:12, coronación). El español batir, el coreano 치다 (golpear/aplaudir). El golpe es autodirigido (palma contra palma) como gesto de emoción o celebración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117835, 'spa', 'forma no verbal', 'Dos formas marcadas como no verbales (1 S 4:13, 2 R 3:24). 1 S 4:13 es una nota marginal ketiv-qeré, 2 R 3:24 puede ser una asignación errónea. Las glosas muestran ''[junto]'' y ''en ella'', lo que sugiere aparato textual más que formas verbales genuinas. Requiere revisión manual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117857, 'spa', 'Herido o contrito', 'El término abarca tanto la incapacidad física (el lisiado de pies en 2 Samuel) como el quebrantamiento espiritual interior (Isaías 66:2, junto a «pobre de espíritu»). Siempre aparece en forma constructa indicando qué parte fue golpeada —pies o espíritu—, subrayando que la aflicción recae sobre un aspecto específico de la persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117858, 'spa', 'Faraón Necao II', 'Necao aparece en Crónicas y Jeremías siempre vinculado a campañas militares y al vasallaje de Judá. La transliteración se mantiene estable en múltiples idiomas (Neco, Néco, Necho), reflejando la transmisión de este nombre real egipcio a través del hebreo. Sus tres apariciones lo conectan con momentos decisivos: la muerte de Josías, la instalación de reyes títeres y la batalla de Carquemis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117861, 'spa', 'Preposición espacial que significa enfrente, frente a o delante de, indicando al', 'Preposición espacial que significa enfrente, frente a o delante de, indicando alineación posicional directa. Se usa para objetos colocados uno ante otro (Éx 26:35), ejércitos acampados cara a cara (1 R 20:29) y la conciencia de estar bajo la mirada de alguien (Pr 5:21). El sentido nuclear es de orientación frontal directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117865, 'spa', 'Extensión figurada del estar frente a alguien hacia el actuar en su favor, emple', 'Extensión figurada del estar frente a alguien hacia el actuar en su favor, empleada en Génesis 25:21 donde Isaac suplica al SEÑOR a favor de Rebeca. La imagen espacial de estar ante Dios se convierte en postura de intercesión, pasando de la ubicación física a la relación personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117866, 'spa', 'Adverbio direccional que significa directamente hacia adelante, indicando movimi', 'Adverbio direccional que significa directamente hacia adelante, indicando movimiento en línea recta y no mera posición estática. Proverbios 4:25 aconseja al joven que dirija su mirada hacia el frente. El impulso de avance distingue este uso del simple estar enfrente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117867, 'spa', 'Recto y honesto', 'Recto, honesto o directo en carácter y conducta. En 2 Samuel 15:3, Absalón dice engañosamente a los peticionarios que sus palabras son «buenas y rectas» (נְכֹחִים), afirmando la legitimidad de sus reclamos. Proverbios 8:9 describe las palabras de la Sabiduría: «todas son rectas (נְכֹחִים) para el que entiende, y directas para quienes hallan conocimiento», pues conducen directamente a la verdad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117868, 'spa', 'Rectitud e integridad', 'Rectitud, honestidad o conducta recta como cualidad moral. En Amós 3:10, se acusa a los opresores: «no saben practicar la rectitud (נְכֹחָה)», pues son incapaces de obrar con justicia. Isaías 26:10 observa que, aun en tierra de rectitud (נְכֹחוֹת), el impío actúa con perversidad. Isaías 30:10 muestra al pueblo rechazando las palabras rectas de los profetas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117869, 'spa', 'Tramar con astucia', 'Ser astuto, engañar o conspirar con astucia calculada. Génesis 37:18 describe a los hermanos de José: «conspiraron contra él (וַיִּתְנַכְּלוּ אֹתוֹ) para matarlo», tramando un plan artero. Números 25:18 advierte contra los madianitas: «os engañaron con sus ardides (נִכְּלוּ לָכֶם נִכְלֵיהֶם)», usando un acusativo cognado que enfatiza la astucia de su engaño en el incidente de Baal-Peor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117872, 'spa', 'Riquezas y bienes', 'Riqueza material, bienes y posesiones vistos como propiedad acumulada. El español «bienes» capta la cualidad tangible e inventariable del término. Aparece frecuentemente junto a עֹשֶׁר y כָּבוֹד formando una tríada de prosperidad (2 Cr 1:11-12; Ecl 6:2). En Eclesiastés 5:19 Dios concede נְכָסִים como don para disfrutar; en Josué 22:8 designa ganado, plata, oro y botín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117874, 'spa', 'El sentido primario en Hifil', 'El sentido primario en Hifil: reconocer o identificar mediante la percepción. José reconoció a sus hermanos pero ellos no lo reconocieron a él (Gn 42:8); las vecinas de Noemí la reconocieron a su regreso (Rt 1:18). Abarca la identificación visual, el discernimiento de voces y la percepción de situaciones a través de evidencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117878, 'spa', 'La expresión הַכֵּר פָּנִים, «reconocer rostros», que significa mostrar parciali', 'La expresión הַכֵּר פָּנִים, «reconocer rostros», que significa mostrar parcialidad o favoritismo, especialmente prohibido en contextos judiciales. Deuteronomio 1:17 y 16:19 prohíben a los jueces «reconocer rostros», mientras Proverbios 24:23 y 28:21 advierten que la parcialidad no es buena.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117884, 'spa', 'Hitpael reflexivo', 'Hitpael reflexivo: darse a conocer o revelar el propio carácter. Proverbios 20:11 dice que incluso un joven «se da a conocer» por sus acciones. Esta única aparición lleva un tono proverbial de autorrevelación a través de los hechos más que de las palabras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117885, 'spa', 'Reconocer o considerar formalmente el estatus o derecho de alguien', 'Reconocer o considerar formalmente el estatus o derecho de alguien. Deuteronomio 21:17 exige que un padre «reconozca» los derechos del primogénito; Isaías 63:16 lamenta que Abraham no «nos reconoce». El sentido va más allá del mero reconocimiento visual hacia la aceptación social o de alianza deliberada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117893, 'spa', 'Piel con fuerza privativa o negativa', 'Piel con fuerza privativa o negativa: rehusar el reconocimiento, negar o desconocer. Job 21:29 desafía a los amigos: «¿No reconocéis sus señales?» El contexto retórico implica una negación deliberada, no accidental, de evidencia obvia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117900, 'spa', 'Piel pasivo-estativo', 'Piel pasivo-estativo: ser considerado o recibir preferencia. Job 34:19 declara que Dios no «considera» al rico por encima del pobre. Esta única aparición hace paralelo con la frase adyacente «no levanta el rostro de los príncipes», confirmando un sentido de trato preferencial que se niega.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117902, 'spa', 'Nifal pasivo', 'Nifal pasivo: ser reconocido o identificado por otros. Lamentaciones 4:8 lamenta que los rostros de los nazareos «no son reconocidos» en las calles debido a la devastación del hambre. La transformación física es tan severa que la identidad misma se pierde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117911, 'spa', 'Disfrazarse, fingir extrañeza', 'Disfrazarse o fingir ser un desconocido (Hitpael reflexivo). José se hace irreconocible ante sus hermanos (Gn 42:7) y la esposa de Jeroboam se disfraza ante Ahías (1 R 14:5-6). En Pr 26:24 el que odia ''se disfraza'' con sus labios: el engaño pasa de la apariencia física a la manipulación verbal, ocultando la hostilidad bajo una fachada de familiaridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117914, 'spa', 'Tergiversar, atribuir mal', 'Tergiversar o atribuir erróneamente, tratando lo familiar como si fuera ajeno (Piel). En Dt 32:27 Moisés advierte que los enemigos de Israel podrían ''tergiversar'' su victoria, atribuyendo a su propio poder lo que en realidad fue juicio divino. Se trata de una distorsión cognitiva que invierte la verdad de los acontecimientos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117915, 'spa', 'Entregar a un extraño', 'Entregar o ceder a alguien a un extraño, apartándolo de su lugar propio (Piel). En 1 S 23:7 Saúl declara que Dios ha ''entregado'' a David en sus manos, aunque el texto hebreo es discutido (la LXX lee מָכַר, ''vendió''). Implica cortar a alguien de la protección divina, tratar a un miembro del pacto como a un forastero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117916, 'spa', 'Profanar, hacer extraño', 'Hacer extraño o profanar, convirtiendo el espacio sagrado en algo ajeno (Piel). En Jer 19:4 el pueblo ha ''hecho extraño este lugar'' al introducir culto pagano. Lo santo del recinto del templo es tratado como si perteneciera a dioses foráneos, borrando su identidad como morada de YHWH.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117918, 'spa', 'Uso sustantivo referido a una persona de origen extranjero', 'Uso sustantivo referido a una persona de origen extranjero: un forastero, ajeno o no israelita. La frase constructa clave es בֶּן־הַנֵּכָר, «hijo de extranjería» = extranjero (Gn 17:12; Éx 12:43; Is 56:3). En 2 Samuel 22:45 el plural «hijos de extranjería» designa a naciones sometidas. El énfasis recae en la persona como forastera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117919, 'spa', 'Sentido abstracto o atributivo', 'Sentido abstracto o atributivo: la cualidad de ser extranjero o ajeno, que típicamente modifica otro sustantivo. Más prominente en la frase אֱלֹהֵי (הַ)נֵּכָר, «dioses de extranjería» = dioses extranjeros (Gn 35:2, 4; Jos 24:20, 23; Jue 10:16). Las traducciones usan adjetivos como «ajeno» o «extraño» en lugar de sustantivos de persona. El singular אֵל נֵכָר, «un dios extraño», aparece en Dt 32:12 y Sal 81:10.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117928, 'spa', 'Adjetivo atributivo que modifica sustantivos', 'Adjetivo atributivo que modifica sustantivos: tierra extranjera (Éx 2:22), mujeres extranjeras (1 R 11:1; Esd 10:2), vestimentas extranjeras (Sof 1:8). El énfasis recae en pertenecer a otro pueblo más que en un juicio moral. Distingue al forastero por origen nacional o étnico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117930, 'spa', 'La «mujer extranjera» (נָכְרִיָּה) de Proverbios', 'La «mujer extranjera» (נָכְרִיָּה) de Proverbios: una figura sustantiva femenina que representa el peligro sexual y moral. Emparejada con אִשָּׁה זָרָה (Pr 2:16; 7:5), simboliza el camino de la insensatez y la muerte. Rut 2:10 ofrece un contrapunto conmovedor: Rut se llama a sí misma נָכְרִיָּה, pero la bondad de Booz derriba la frontera social esperada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117931, 'spa', 'Uso sustantivo masculino', 'Uso sustantivo masculino: el extranjero como categoría legal distinta del גֵּר (residente protegido). La legislación económica de Deuteronomio permite cobrar interés al נָכְרִי (Dt 23:20) y venderle carne de animal muerto (Dt 14:21). La oración de Salomón en 1 Reyes 8:41 contempla al נָכְרִי viniendo de lejos para adorar en el Templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117952, 'spa', 'Tesoro real', 'La palabra aparece exclusivamente en el relato de Ezequías, donde el rey exhibe sus riquezas acumuladas ante los mensajeros de Babilonia, un acto que Isaías condena como proféticamente peligroso. La forma בֵּית נְכֹתֹה (su casa del tesoro) sugiere un recinto específico destinado a almacenar las posesiones reales, acentuando la concentración de riqueza y la imprudencia de su exhibición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117955, 'spa', 'Nombre personal bíblico', 'Las tres apariciones del nombre se encuentran en contextos genealógicos y censales en Números y Crónicas. El Nemuel simeonita encabeza un clan (los nemuelitas), mientras que el rubenita es mencionado para situar a Datán y Abiram dentro de su linaje familiar. Las traducciones multilingües muestran simple transliteración con variaciones preposicionales que reflejan el estado constructo hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117957, 'spa', 'Marchitarse y languidecer', 'Marchitarse, desvanecerse o languidecer, describiendo un declive semejante al de las plantas. El Salmo 37:2 promete que los impíos «pronto se marchitarán como la hierba (יִמָּלְלוּ)», en paralelo con «se secarán como el pasto verde». Job 14:2 lamenta la fragilidad humana: el hombre «brota como una flor y se marchita (וַיִּמָּל)», ilustrando la brevedad de la vida con una flor que se ajá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117961, 'spa', 'Leopardo (animal)', 'El leopardo (Panthera pardus), gran felino depredador conocido por su pelaje moteado, velocidad y sigilo. Los escritores biblicos lo emplean en lenguaje figurado y profetico: Jeremias 13:23 usa sus manchas inalterables como imagen proverbial; Habacuc 1:8 resalta su rapidez; Oseas 13:7 compara el juicio divino con un leopardo al acecho; e Isaias 11:6 lo situa en la paz mesianica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117967, 'spa', 'Nombre propio: Nimrod', 'La figura histórica o legendaria de Nimrod aparece exclusivamente como nombre propio en Génesis, Crónicas y Miqueas. La evidencia multilingüe lo trata uniformemente como un nombre personal transliterado, manteniendo la forma hebrea en los idiomas europeos. Génesis 10:8-9 establece su fama como cazador y constructor de ciudades, mientras que la «tierra de Nimrod» en Miqueas demuestra su perdurable asociación con el poderío asirio-babilónico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117969, 'spa', 'Ancestro de Jehú', 'Nimsí, ancestro del rey Jehú, usado exclusivamente en el patronímico «Jehú hijo de Nimsí». Las cinco apariciones funcionan como fórmula fija de identificación tanto en Reyes como en Crónicas. La designación vincula la dinastía de Jehú con un linaje reconocido, desde la comisión profética de Elías (1 R 19:16) hasta el relato del golpe (2 R 9:2, 14, 20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117970, 'spa', 'El sentido dominante de bandera, estandarte o enseña militar alzada en una altur', 'El sentido dominante de bandera, estandarte o enseña militar alzada en una altura prominente como punto de reunión o señal, abarcando 17 de las 20 apariciones. Isaías lo emplea repetidamente como señal escatológica de Dios a las naciones (Is 5:26, 11:10, 11:12, 13:2, 18:3, 49:22, 62:10). La raíz de Jesé ''se alzará como estandarte para los pueblos'' (Is 11:10), convirtiendo la imagen militar en mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117971, 'spa', 'Un sentido físico concreto de asta, mástil o pértiga sobre la que se exhibe o mo', 'Un sentido físico concreto de asta, mástil o pértiga sobre la que se exhibe o monta algo. En Números 21:8-9, Dios instruye a Moisés a hacer una serpiente de bronce y colocarla ''sobre un asta'' (עַל־נֵס) — aquí la palabra designa el objeto mismo en lugar de lo que señala. Isaías 33:23 puede extender esto al mástil de un barco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117975, 'spa', 'Un uso poco frecuente como señal de advertencia u objeto de escarmiento alzado p', 'Un uso poco frecuente como señal de advertencia u objeto de escarmiento alzado para visibilidad pública. En Números 26:10 la tierra tragó a la compañía de Coré y ellos se convirtieron ''en señal'' (לְנֵס) — su destrucción exhibida como ejemplo de cautela permanente. El evento mismo es alzado, metafóricamente, como advertencia visible para la comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117979, 'spa', 'Mover, remover (lindero)', 'Hifil: mover o remover un mojón, el desplazamiento ilícito de un lindero del prójimo. Es el sentido más frecuente y el de mayor carga cultural, ya que las piedras limítrofes garantizaban la herencia ancestral de cada familia en la tierra prometida. Deuteronomio 19:14 y 27:17 colocan este acto bajo maldición solemne, mientras Proverbios 22:28 y 23:10 extienden la prohibición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117980, 'spa', 'Ser rechazado, repelido', 'Hofal (pasivo del Hifil): ser rechazado o expulsado por una fuerza externa. Isaías 59:14 declara que la justicia ''fue rechazada'' en la plaza pública, empleando la voz pasiva para enfatizar que el juicio recto ha sido violentamente expulsado por poderes corruptos. La naturaleza involuntaria de este desplazamiento subraya la gravedad de la injusticia sistémica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117984, 'spa', 'Apartar, quitar', 'Hifil: remover o apartar algo más allá del dominio específico de las piedras limítrofes. En Miqueas 6:14, Dios pronuncia juicio: ''apartarás pero no rescatarás'', describiendo intentos fútiles de salvar posesiones bajo disciplina divina. Este sentido generaliza el Hifil desde el contexto de linderos hacia cualquier acto de quitar o remover.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117985, 'spa', 'Retroceder, retirarse', 'Nifal: retroceder, retirarse o apartarse de forma intransitiva. En Isaías 59:13, la justicia se describe ''retrocediendo'' de la comunidad, personificando la rectitud como una figura que se retira ante la opresión. Miqueas 2:6 emplea la forma en el contexto del silenciamiento de la palabra profética. Este sentido extiende la imagen del lindero al ámbito moral y espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117987, 'spa', 'Los humanos probando a Dios de manera rebelde, exigiendo demostración de su pode', 'Los humanos probando a Dios de manera rebelde, exigiendo demostración de su poder o presencia. Éxodo 17:2 en Masá es el pasaje definitorio: «¿Por qué tentáis al SEÑOR?» Números 14:22 acusa a Israel de tentar a Dios diez veces. Deuteronomio 6:16 codifica la prohibición: «No tentaréis al SEÑOR vuestro Dios.» Los Salmos 78:18, 41, 56 y 95:9 recuerdan estas provocaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117988, 'spa', 'Dios (o una autoridad legítima) poniendo a prueba a los seres humanos para exami', 'Dios (o una autoridad legítima) poniendo a prueba a los seres humanos para examinar su fe, carácter u obediencia. Génesis 22:1 — «Dios probó a Abraham» — ancla este sentido teológicamente. Éxodo 15:25, 16:4 y 20:20 establecen el patrón de prueba en el desierto. Deuteronomio 8:2, 16 y 13:3 presentan la prueba como pedagógica: Dios prueba a Israel para saber lo que hay en su corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (117994, 'spa', 'Intentar, atreverse o aventurarse a hacer algo sin precedentes o difícil', 'Intentar, atreverse o aventurarse a hacer algo sin precedentes o difícil. Deuteronomio 4:34 pregunta retóricamente si algún dios ha «intentado» tomar una nación de dentro de otra. Deuteronomio 28:56 describe a la mujer delicada que nunca se ha «atrevido» a poner el pie en el suelo. Job 4:2 pregunta: «Si se intenta una palabra contigo, ¿te fatigarás?»');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118016, 'spa', 'Arrancar con violencia', 'Arrancar, desarraigar o remover por la fuerza. Proverbios 2:22 contrasta el destino de justos e impíos: los transgresores serán arrancados de la tierra. Proverbios 15:25 declara que YHWH derriba la casa de los soberbios. Salmo 52:5 advierte al engañoso que Dios lo arrancará y lo arrebatará de su morada para siempre, con una finalidad destructiva e irrevocable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118019, 'spa', 'Príncipes extranjeros', 'Príncipes o caudillos, especialmente de pueblos enemigos o extranjeros. Josué 13:21 enumera a los príncipes de Sijón, reyes madianitas derrotados cuando Moisés venció a Sijón rey de los amorreos. Salmo 83:11 recuerda estas victorias en oración, pidiendo que sus nobles y príncipes corran la misma suerte que Oreb, Zeeb, Zeba y Zalmuna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118020, 'spa', 'Derramar una libación u ofrenda líquida en forma causativa (Hifil/Piel) — el sen', 'Derramar una libación u ofrenda líquida en forma causativa (Hifil/Piel) — el sentido cúltico dominante con 15 ocurrencias. Abarca el derramamiento formal de ofrendas líquidas en el sistema del santuario (Nm 28:7), libaciones memoriales sobre pilares sagrados (Gn 35:14) y el dramático gesto de David al derramar el agua de Belén como sacrificio (2 S 23:16; 1 Cr 11:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118023, 'spa', 'Fundir metal, especialmente para la fabricación de ídolos — 2 ocurrencias en Qal', 'Fundir metal, especialmente para la fabricación de ídolos — 2 ocurrencias en Qal con sentido técnico especializado. En Isaías 40:19 un artesano ''funde'' un ídolo, y en Isaías 44:10 el profeta se burla de quienes ''funden'' una imagen metálica que para nada sirve. El hebreo mismo no distingue morfológicamente entre derramar líquido y verter metal fundido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118027, 'spa', 'Ser derramado (Hofal pasivo) — 2 ocurrencias que describen recipientes de los cu', 'Ser derramado (Hofal pasivo) — 2 ocurrencias que describen recipientes de los cuales se vierte líquido. En Éxodo 25:29 y 37:16 los jarrones de oro del tabernáculo se describen como aquellos ''con los cuales se derrama la libación''. Estas descripciones del mobiliario cúltico completan el cuadro: no solo el acto de derramar, sino los instrumentos destinados a ello.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118028, 'spa', 'Derramar una libación en la conjugación básica Qal — 4 ocurrencias donde la voz ', 'Derramar una libación en la conjugación básica Qal — 4 ocurrencias donde la voz activa simple basta sin intensificación causativa. En Éxodo 30:9 se prohíben ofrendas líquidas ajenas sobre el altar del incienso; Oseas 9:4 advierte que sus sacrificios no agradarán al SEÑOR. Isaías 29:10 extiende la metáfora de modo llamativo: Dios ha ''derramado'' sobre ellos espíritu de sopor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118040, 'spa', 'Ofrenda líquida o libación, un líquido (generalmente vino) derramado como parte ', 'Ofrenda líquida o libación, un líquido (generalmente vino) derramado como parte del culto sacrificial. Este sentido representa 60 de las 64 ocurrencias, profundamente arraigado en la legislación sacerdotal de Números 15 y 28-29. La evidencia multilingüe apunta uniformemente a ofrendas líquidas rituales: el alemán Trankopfer (''sacrificio líquido''), el francés boire-offrande (''ofrenda de beber'') y el español libación especifican el derramamiento ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118046, 'spa', 'Una imagen fundida o ídolo de metal formado vertiendo metal en un molde', 'Una imagen fundida o ídolo de metal formado vertiendo metal en un molde. Aunque comparte la misma grafía consonántica, este sentido deriva de la raíz que significa ''fundir, verter metal''. Con cuatro apariciones en la condena profética, se traduce distintamente: español imagen fundida, inglés ''molten image'' y hindi dhali hui murti (''ídolo fundido''). Isaías 41:29 declara que los ídolos y sus imágenes fundidas no son más que viento y vacío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118066, 'spa', 'partir, viajar (Qal)', 'El sentido nuclear Qal: arrancar el campamento y ponerse en camino, partir, viajar o marchar. Es el verbo dominante de la narración del desierto con 133 apariciones — Gn 12:9 registra a Abram ''caminando'' (נָסוֹעַ) hacia el Neguev, y Nm 10:12-36 coreografía toda la marcha tribal con usos repetidos. El español partieron y el francés voyagèrent traducen fielmente esta partida-y-travesía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118084, 'spa', 'hacer partir, guiar (Hifil)', 'El Hifil causativo en su sentido de conducción de marcha: hacer partir, guiar en el camino. Éx 15:22 narra cómo Moisés hizo partir a Israel del mar Rojo; Sal 78:52 celebra a Dios que ''condujo a su pueblo como ovejas''. Sal 78:26 extiende el uso a Dios haciendo ''soplar'' el viento del este por los cielos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118093, 'spa', 'desarraigar, cantear (Hifil)', 'El Hifil causativo en su sentido físico-concreto: desarraigar, cantear piedra, remover o transportar. 1 R 5:17 describe obreros que ''cantearon'' grandes piedras para los cimientos del templo. Sal 80:8 recuerda a Dios que ''arrancó'' una vid de Egipto y la trasplantó a Canaán. Job 19:10 lamenta que Dios ''ha arrancado mi esperanza como un árbol''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118101, 'spa', 'ser arrancado (Nifal pasivo)', 'Nifal pasivo: ser arrancado, desarraigado o desplazado. Is 33:20 promete que las estacas de Jerusalén ''no serán jamás arrancadas'' — la imagen concreta original como metáfora de permanencia. Is 38:12 compara la vida con una tienda ''arrancada y trasladada''. Job 4:21 pregunta si las cuerdas ''no son arrancadas'' al morir sin sabiduría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118106, 'spa', 'arrancar, extraer (Qal literal)', 'El Qal concreto literal: arrancar o extraer físicamente un objeto — la acción original que subyace a todas las extensiones semánticas. Jue 16:3 relata cómo Sansón arrancó las puertas de la ciudad con sus postes y barra, y Jue 16:14 describe cómo arrancó la clavija del telar. Con solo dos atestiguaciones, conserva la fuerza física primaria del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118122, 'spa', 'Ascender o hacer subir', 'Daniel y Esdras emplean este verbo tanto para el ascenso visionario como para el concreto. En Daniel 7:3, cuatro bestias «suben del mar»; en 7:8, un cuerno «surge» entre los diez. Las formas causativas en Daniel 3:22 y 6:23 describen el acto de sacar o hacer subir a personas del horno de fuego y del foso de los leones, reflejando la direccionalidad ascendente del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118125, 'spa', 'Hija de Zelofehad', 'Nombre propio femenino de una de las cinco hijas de Zelofehad, de la tribu de Manasés. Números 26:33 la incluye entre Mahlá, Noá, Hoglá, Milcá y Tirsá. Números 27:1 relata cómo estas hijas se presentaron ante Moisés para reclamar derechos de herencia, ya que su padre murió sin hijos varones, estableciendo un caso jurídico sin precedentes. Números 36:11 registra sus matrimonios dentro de su propio clan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118126, 'spa', 'El período de ser joven, que abarca desde la niñez hasta la adultez temprana, de', 'El período de ser joven, que abarca desde la niñez hasta la adultez temprana, denotando inmadurez, desarrollo formativo o la etapa más temprana de la vida. Rige frecuentemente la frase preposicional מִנְּעוּרַי («desde mi juventud»), que sirve como fórmula biográfica — ya sea confesando pecado de toda la vida (Gn 8:21; 1 S 12:2), profesando devoción de toda la vida (Sal 71:5, 17), o caracterizando la historia temprana de una nación (Jer 2:2; 48:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118148, 'spa', 'Agradable, deleitoso', 'Describe personas, experiencias o cualidades que producen genuino deleite y placer estético. Se aplica a David y Jonatán como «amables y agradables» en la elegía de Saúl (2 Sam 1:23), a las líneas de heredad que caen en lugares deleitosos (Sal 16:6), a la dulzura de alabar a Dios (Sal 135:3; 147:1) y al provecho de las palabras sabias guardadas en los labios (Prov 22:18). Job 36:11 promete que los obedientes pasarán sus días en bienestar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118157, 'spa', 'Cerrar con cerrojo', 'Asegurar una puerta o portada con cerrojo o tranca, dejandola firmemente cerrada. La raiz Qal aparece en formas activas (Jue 3:23, 2 Sam 13:17-18) describiendo el acto fisico de atrancar puertas, y en participios pasivos (Cnt 4:12) que expresan el estado de estar cerrado. Las puertas atrancadas en Jueces generan ironia dramatica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118162, 'spa', 'Suela de cuero atada al pie con correas — el calzado estándar del Israel bíblico', 'Suela de cuero atada al pie con correas — el calzado estándar del Israel bíblico. Se usa literalmente para calzar, descalzar o poseer sandalias en contextos que van desde la preparación militar (Is 5:27) hasta las provisiones de viaje (Éx 12:11; Jos 9:5, 13). Tiene fuerza jurídico-simbólica en la ceremonia del levirato (Dt 25:9-10) y en declaraciones proféticas de dominio (Sal 60:10). Amós 2:6 y 8:6 evocan un par de sandalias como imagen de valor despreciable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118180, 'spa', 'Ser agradable, deleitoso', 'Ser agradable, placentero o encantador en cualidad o experiencia. El verbo funciona como estativo que describe una amenidad inherente: la belleza reposada de una tierra (Gn 49:15, ''vio que el reposo era bueno y la tierra agradable''), la dulzura emocional de un compañero amado (2 S 1:26, ''me fuiste más agradable''), y el deleite de las palabras sabias cuando se interiorizan (Pr 2:10; 24:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118188, 'spa', 'Amenidad, hermosura, favor', 'Cualidad abstracta de amenidad, deleite, hermosura o favor benigno, atribuida a Dios o a los caminos de la sabiduría. En Sal 27:4 el adorador desea contemplar la נֹעַם (belleza/deleite) del SEÑOR en su templo; Sal 90:17 pide que el favor divino afiance las obras humanas. Proverbios la emplea en cadenas constructas: ''caminos de amenidad'' (3:17), ''palabras de agrado'' (15:26; 16:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118189, 'spa', 'Gracia (nombre simbólico)', 'Nombre propio simbólico, ''Gracia'' o ''Favor'', dado a uno de los dos cayados pastoriles en la acción profética de Zacarías (Zac 11:7, 10). El cayado representa el pacto de gracia de Dios con las naciones en favor de Israel; cuando el profeta lo quiebra, el pacto queda anulado. La tradición lo traduce como Gracia, grâce o Pleasantness, personificando el favor divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118193, 'spa', 'Nombre propio femenino', 'Nombre propio femenino de dos mujeres bíblicas. (1) Hermana de Tubal-Caín, mencionada en la genealogía de Caín (Gn 4:22): única mujer nombrada en esa línea además de Eva, aunque su importancia permanece sin explicar. (2) Princesa amonita, esposa de Salomón y madre de Roboam (1 R 14:21, 31; 2 Cr 12:13), cuyo origen extranjero se vincula con la idolatría salomónica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118196, 'spa', 'Nombre propio de la suegra de Rut, que aparece exclusivamente en el libro de Rut', 'Nombre propio de la suegra de Rut, que aparece exclusivamente en el libro de Rut (las 21 apariciones). El nombre mismo significa ''agradable'' o ''encantadora'', lo cual Noemí contrasta punzantemente con Mará (''amarga'') en Rut 1:20 tras su duelo. Ella funciona como arquitecta narrativa cuyo regreso a Belén, consejo a Rut y papel en el rescate por parte de Booz desembocan en el nacimiento de Obed, abuelo de David, insertándola discretamente en la genealogía mesiánica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118200, 'spa', 'Nombre propio masculino que identifica a personajes bíblicos llamados Naamán (''a', 'Nombre propio masculino que identifica a personajes bíblicos llamados Naamán (''agradable''). El general arameo domina el uso (doce de dieciséis apariciones en 2 Re 5), cuya dramática sanación de la lepra al bañarse en el Jordán se convirtió en relato paradigmático de la fe gentil. Las apariciones restantes identifican a un ancestro benjaminita (Gn 46:21; Núm 26:40). La Septuaginta transcribe el nombre como Naiman/Neemán, y Jesús mismo citó la sanación de Naamán como evidencia de que la misericordia de Dios se extiende a los de fuera (Lc 4:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118203, 'spa', 'Gentilicio de Zofar', 'Adjetivo gentilicio que indica el origen geográfico o clan de Zofar. Las cuatro apariciones se encuentran en Job como «Zofar el naamatita» (הַנַּעֲמָתִי): presentado en Job 2:11 entre los tres amigos que llegan a consolar a Job, y mencionado en 11:1, 20:1 cuando Zofar habla, y en 42:9 en la conclusión narrativa. Sugiere conexión con un lugar o clan llamado Naamá, de ubicación desconocida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118206, 'spa', 'Sacudir vigorosamente (Piel)', 'Piel intensivo: sacudir o arrojar con violencia decidida. Dios sacudió los carros del faraón en el mar Rojo (Éx 14:27; Sal 136:15), y Nehemías invocó el mismo verbo en su maldición juratoria: «Así sacuda Dios a todo hombre de su casa» (Neh 5:13). El español «arrojó» y «sacudió» transmiten la fuerza violenta y expulsiva de esta forma intensiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118207, 'spa', 'Sacudir (Qal activo)', 'Qal activo: sacudir o quitar algo mediante acción física en la forma básica. Nehemías sacudió su vestidura como acto simbólico (Neh 5:13), Isaías 33:15 describe al justo que «sacude sus manos para no aceptar soborno», e Isaías 33:9 presenta las hojas del Líbano siendo sacudidas por el juicio marchitante. El sentido es remoción deliberada mediante agitación física, menos violenta que el Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118208, 'spa', 'Ser sacudido (pasivo)', 'Voz pasiva (participio pasivo Qal y Nifal): ser sacudido o desprendido. El salmista lamenta «soy sacudido como langosta» (Sal 109:23), evocando la imagen de un insecto apartado de un pliegue del vestido — metáfora poderosa de sentirse descartable y desarraigado. En Job 38:13, los impíos son «sacudidos» de la tierra al amanecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118211, 'spa', 'Sacudirse, liberarse (reflexivo)', 'Hitpael y Nifal reflexivo: sacudirse del polvo, las ataduras o el cautiverio. Isaías 52:2 ordena a Sion: «¡Sacúdete del polvo, levántate!» — un llamado a la autoliberación que une libertad física y espiritual. Sansón «se sacudió» esperando la fuerza divina (Jue 16:20), sin saber que el SEÑOR se había apartado de él.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118217, 'spa', 'joven, mozo', 'Joven o mozo en la plenitud de su vigor (122x), que subraya la etapa vital entre la niñez y la plena madurez. Dicho de José a los diecisiete años (Gn 37:2), del joven Absalón y de grupos de hombres en edad de combatir. El coreano 젊은이 y el español joven seleccionan sistemáticamente vocabulario centrado en la edad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118220, 'spa', 'niño, infante', 'Niño pequeño o infante (47x), que enfatiza la tierna edad. Dicho del bebé Moisés a los tres meses (Éx 2:6), del niño Samuel, del muchacho Ismael (Gn 21:12-19) y de recién nacidos (1 S 4:21). El árabe صَبِيٌّ, el coreano 아이 y el español niño seleccionan vocabulario propio de la infancia, confirmando distancia semántica respecto a la acepción 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118223, 'spa', 'criado, sirviente', 'Criado, sirviente o servidor personal (67x), donde prima el rol social más que la edad. Incluye escuderos (Jue 7:10-11), Giezi al servicio de Eliseo (2 R 4:24) y sirvientes domésticos. El árabe خَادِمٌ y el español criado/siervo emplean vocabulario específico de servicio, distinto de las glosas de ''joven''. La construcción posesiva ''su נַעַר'' (נַעֲרוֹ) señala casi siempre esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118254, 'spa', 'desde la juventud (temporal)', 'Uso temporal que significa ''desde la juventud / desde joven'' (3x), en expresiones como מִנַּעַר (''desde ser נַעַר''). En Gn 19:4 y Jos 6:21 aparece en el merismo ''desde joven hasta viejo'' para denotar totalidad. El árabe مِن صِغَرِهِ y el español desde joven lo traducen como punto de origen temporal, no como persona.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118314, 'spa', 'Juventud o vida temprana', 'Designa el periodo o estado de la juventud y la vida temprana. Las glosas hebreas se traducen uniformemente como «desde la juventud» o «en la juventud», apareciendo en contextos donde la lozanía juvenil se restaura (Job 33:25) o sirve como marcador temporal para condiciones que abarcan toda la vida (Salmo 88:15, Proverbios 29:21). La evidencia multilingüe confirma construcciones temporales-prepositivas en diversos idiomas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118315, 'spa', 'El singular designa típicamente a una mujer joven individual en edad casadera, c', 'El singular designa típicamente a una mujer joven individual en edad casadera, como cuando el siervo de Abraham oró para que ''la joven'' que le ofreciera agua fuese la esposa de Isaac (Gn 24:14, 16). El alemán jung Frau y el francés jeune-femme conservan la designación de etapa vital. Este sentido se centra en la posición social y la aptitud para el matrimonio más que en un estatus subordinado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118322, 'spa', 'El plural con sufijo posesivo designa a asistentes femeninas o criadas perteneci', 'El plural con sufijo posesivo designa a asistentes femeninas o criadas pertenecientes a un hogar. Rebeca llevó ''sus jóvenes'' cuando partió hacia Isaac (Gn 24:61), la hija del faraón tenía ''sus doncellas'' junto al Nilo cuando encontró a Moisés (Éx 2:5), y Booz dijo a Rut que se quedara junto a ''mis muchachas'' espigando en sus campos (Rt 2:8, 22, 23). El español criadas capta el matiz de servicio doméstico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118323, 'spa', 'En ciertos contextos, el plural absoluto designa a las mujeres jóvenes como grup', 'En ciertos contextos, el plural absoluto designa a las mujeres jóvenes como grupo colectivo sin implicar servidumbre. Cuando los siervos de Saúl buscaban ''muchachas'' que iban a sacar agua para que les indicaran dónde estaba el vidente Samuel (1 S 9:11), o cuando los servidores de Asuero propusieron reunir ''jóvenes'' hermosas para que el rey eligiera reina (Est 2:2, 8), el término funciona como una categoría de edad y género.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118349, 'spa', 'Nombre propio femenino', 'Las tres apariciones se concentran en 1 Crónicas 4:5-6, donde Naara figura como madre de varios hijos en el linaje de Judá. Algunos traductores confunden el nombre propio con el sustantivo común «joven», difuminando la frontera entre ambos usos. El contexto genealógico deja claro que se trata de un nombre personal, aunque la coincidencia semántica con «muchacha» pudo ser intencionada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (118351, 'spa', 'Nombre propio masculino', 'Ambas apariciones se enmarcan en contextos genealógicos: una traza la línea real de David y la otra documenta el liderazgo militar simeonita. La evidencia multilingüe muestra una transliteración sencilla con mínima variación (Nearya, Nearías), indicando que se entendía como nombre propio sin traducción semántica adicional. Los dos Nearías representan afiliaciones tribales distintas (Judá y Simeón).');